-- A sheet's parent sheet (null means none; not dated): a grade with no rate in force on a date on the sheet
-- takes its parent's rate for that grade and date, then the parent's parent's, up to three levels up.
ALTER TABLE sheet ADD COLUMN parent_id VARCHAR(200);
-- A person's aliases: other names they are known by on the sheet. An alias shares the names' uniqueness
-- (ignoring case, no alias equals any name or alias on the sheet), checked when one is added.
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(500) NOT NULL
);
CREATE INDEX person_alias_sheet ON person_alias (sheet_id, person_id);
-- A person's name is unique on its sheet, compared without regard to case (names are stored trimmed).
ALTER TABLE person ADD COLUMN name_key VARCHAR(500) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
