package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.web.bind.annotation.PathVariable;

public class AddPerson {
    public void add(@PathVariable("sheetId") String sheetId, @Val PersonRequest request,
            ServerHttpConnection connection, PersonRepository repository, Audit audit, Rollup rollup, Out<Person> person)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        if (repository.nameTaken(id, request.name(), 0)) {
            throw new BadRequestException("name is already in use");
        }
        String contact = request.contact().isEmpty() ? null : request.contact();
        if (contact != null && repository.contactTaken(id, contact, 0)) {
            throw new BadRequestException("contact is already in use");
        }
        Rollup.Snapshot before = rollup.take(id);
        Person added;
        try {
            added = repository.add(id, request.name(), request.grade(),
                    request.terms().isEmpty() ? null : Integer.valueOf(request.terms()), contact);
        } catch (DuplicateKeyException e) {
            throw new BadRequestException("name is already in use");
        }
        audit.record("PERSON_ADDED sheet=" + id + " by=" + by + " name=" + added.name()
                + " grade=" + added.grade() + (added.terms() == null ? "" : " terms=" + added.terms())
                + (added.contact() == null ? "" : " contact=" + added.contact()));
        rollup.record(id, by, before);
        person.set(added);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.ConflictException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.web.bind.annotation.PathVariable;

/** Save an edited person; refused (409) when someone else has saved them since the editor loaded its version.
 *  The form's grade is recorded from its from-date (blank: the sheet's today), keeping their other grades,
 *  except that a save leaving the grade in force on the sheet's today as it is, with the from-date blank,
 *  records no grade. PERSON_EDITED carries the grade in force on the sheet's today after the save, then
 *  the person's own terms when the save changed them (empty when it cleared them), then their contact when
 *  the save changed it (empty when it cleared it). */
public class SavePerson {
    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @Val PersonRequest request, ServerHttpConnection connection, PersonRepository repository,
            SheetRepository sheets, Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException, ConflictException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        if (request.version() == null) {
            throw new BadRequestException("version is required");
        }
        if (!repository.exists(id, pid)) {
            throw new BadRequestException("no such person");
        }
        if (repository.nameTaken(id, request.name(), pid)) {
            throw new BadRequestException("name is already in use");
        }
        Person current = repository.find(id, pid);
        // a stale editor is told so (and shown the current values) before its contact is judged against them
        if (current.version() != request.version()) {
            throw new ConflictException("someone else has saved this person; showing their current values");
        }
        String contact = request.contact().isEmpty() ? null : request.contact();
        if (contact != null && repository.contactTaken(id, contact, pid)) {
            throw new BadRequestException("contact is already in use");
        }
        boolean regrade = !request.gradeFrom().isEmpty() || !request.grade().equals(current.grade());
        LocalDate from = request.gradeFrom().isEmpty() ? sheets.today(id) : LocalDate.parse(request.gradeFrom());
        Integer terms = request.terms().isEmpty() ? null : Integer.valueOf(request.terms());
        boolean reterm = !java.util.Objects.equals(terms, current.terms());
        boolean recontact = !java.util.Objects.equals(contact, current.contact());
        long version = request.version();
        Rollup.Snapshot before = rollup.take(id);
        boolean updated;
        try {
            updated = repository.update(id, pid, version, request.name(), terms, contact);
        } catch (DuplicateKeyException e) {
            throw new BadRequestException("name is already in use");
        }
        if (!updated) {
            throw new ConflictException("someone else has saved this person; showing their current values");
        }
        if (regrade) {
            repository.grade(id, pid, request.grade(), from);
        }
        Person saved = repository.find(id, pid);
        audit.record("PERSON_EDITED sheet=" + id + " by=" + by + " name=" + saved.name()
                + " grade=" + saved.grade() + (reterm ? " terms=" + (terms == null ? "" : terms) : "")
                + (recontact ? " contact=" + (contact == null ? "" : contact) : ""));
        rollup.record(id, by, before);
        person.set(saved);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Give a person an alias (trimmed; required): it must not equal, ignoring case, any name or alias on the sheet. */
public class AddAlias {
    public void add(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @RequestBody AliasRequest request, ServerHttpConnection connection, PersonRepository repository,
            AliasRepository aliases, Audit audit, Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person found = repository.find(id, pid);
        if (found == null) {
            throw new BadRequestException("no such person");
        }
        String alias = request == null || request.alias() == null ? "" : request.alias().trim();
        if (alias.isEmpty()) {
            throw new BadRequestException("alias is required");
        }
        if (repository.nameTaken(id, alias, 0)) {
            throw new BadRequestException("name is already in use");
        }
        aliases.add(id, pid, alias);
        audit.record("PERSON_ALIAS_ADDED sheet=" + id + " by=" + by + " name=" + found.name() + " alias=" + alias);
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** A person on a sheet: the id the store assigned, their name and the grade (A, B or C) in force on
 *  the sheet's today, with every grade they have been given (oldest first), and the
 *  version of these values (up by one on each save), and their statements: how many have been taken,
 *  and the last one's due-total and date (both null before the first), and the date they are retired
 *  from (null when not retired; any date set means retired at once), and their holds (oldest first) and
 *  whether they have any (their open (OPEN or PENDING) claims dated within a hold, unless bound by a
 *  statement, then count in no live total), and their own terms in days (null when they have none), and their contact (null when they have none). */
public record Person(long id, String name, String grade, long version, long statementCount,
        String statedTotal, String statementDate, String retiredFrom, boolean held, List<GradeFrom> grades,
        List<Hold> holds, Integer terms, String contact) {

    public Person withGrades(List<GradeFrom> grades) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact);
    }

    public Person withHolds(List<Hold> holds) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom,
                !holds.isEmpty(), grades, holds, terms, contact);
    }

    public boolean retired() {
        return retiredFrom != null;
    }

    /** Their holds as they act on live totals on the sheet's today: once their retirement date is reached
     *  (the sheet's today on or after it) they are held over every date as well. */
    public List<Hold> liveHolds(String today) {
        if (retiredFrom == null || today == null || retiredFrom.compareTo(today) > 0) return holds;
        List<Hold> all = new java.util.ArrayList<>(holds);
        all.add(new Hold(null, null));
        return all;
    }
}
