useAsOf.ts
import { useState } from 'react';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useAsOf } from './useAsOf';

/** Show the sheet as of a date: every cell then shows the sheet as it stood at the end of that day (the
 *  date standing in for the sheet's today), and every change is refused, until it is cleared. */
function AsOfControl() {
  const [asOf, setAsOf] = useAsOf();
  const [date, setDate] = useState('');
  return (
    <form
      data-testid="asof-form"
      onSubmit={(e) => {
        e.preventDefault();
        const want = date.trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(want)) setAsOf(want);
      }}
    >
      As of: <strong data-testid="sheet-asof">{asOf}</strong>{' '}
      <label>
        Show as of{' '}
        <input
          type="text"
          placeholder="yyyy-mm-dd"
          data-testid="asof-date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
        />
      </label>{' '}
      <button type="submit" data-testid="asof-set">
        Set
      </button>{' '}
      <button type="button" data-testid="asof-clear" onClick={() => setAsOf(undefined)}>
        Clear
      </button>
    </form>
  );
}

export const contribution = SheetBody.fill({ order: 1, Component: () => <AsOfControl /> });
import { useEffect, useRef } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { currentAsOfDate, setAsOfDate } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';

/** The date this screen shows the sheet as of (URL key `asOf`; '' when it shows the sheet as it is now).
 *  It belongs to this user's screen only, and is left as it is by loading a sheet. Every request is sent
 *  with it, so a change of it re-reads every query. */
export function useAsOf(): [string, (date: string | undefined) => void] {
  const [asOf, setAsOf] = useSearchParam('asOf', asString);
  const queryClient = useQueryClient();
  const changed = useRef(false);
  if (currentAsOfDate() !== asOf) {
    setAsOfDate(asOf);
    changed.current = true;
  }
  useEffect(() => {
    if (!changed.current) return;
    changed.current = false;
    void queryClient.resetQueries();
  }, [asOf, queryClient]);
  return [asOf, setAsOf];
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data. The rejection's message is the
// server's own `error` text when it sent one.
//
// Every request carries the signed-in name in X-User (the server records it as `by=<user>`), and,
// while this screen shows the sheet as of a date, that date in X-As-Of: reads answer as the sheet stood
// then, and every change is refused.
let signedInUser = '';
let asOfDate = '';

/** A non-2xx answer: the server's message, and its status (409 when someone else saved first). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** Called by the session (features/session) whenever the signed-in name changes. */
export function setSignedInUser(name: string): void {
  signedInUser = name;
}

/** Called by the as-of control (features/asof) whenever the screen's as-of date changes ('' when none). */
export function setAsOfDate(date: string): void {
  asOfDate = date;
}

/** The as-of date requests are sent with ('' when none). */
export function currentAsOfDate(): string {
  return asOfDate;
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const headers = new Headers(init?.headers);
  if (signedInUser) headers.set('X-User', signedInUser);
  if (asOfDate) headers.set('X-As-Of', asOfDate);
  const res = await fetch(path, { ...init, headers });
  if (!res.ok) {
    let message = `${init?.method ?? 'GET'} ${path} -> ${res.status}`;
    try {
      const body = (await res.json()) as { error?: string };
      if (body?.error) message = body.error;
    } catch {
      /* no JSON body: keep the status message */
    }
    throw new HttpError(message, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });

